  .split-line-p {
    --bg-progress: 0;
    color: transparent;
    background: linear-gradient(
      90deg,
      var(--color-final, var(--_color---content--main)) 0%,
      var(--color-final, var(--_color---content--main)) 30%,

      var(--_color---content--brand) 40%,
      transparent 50%,

      transparent 60%,
      transparent 100%
    );
    background-size: 350% 100%;

    background-position-x: calc((100 - var(--bg-progress)) * 1%);
    background-clip: text;
  }
  .split-line-p span {
    display: block;
  }
  .line-mask {
    overflow: hidden;
  }

  .line-inner {
    display: block;
    will-change: transform;
  }
  .txt:not(.w-input):empty {
    display: none;
  }
  .hover-un {
    position: relative;
    width: fit-content;
    cursor: pointer;
    color: currentColor;
  }
  .hover-un::before {
    content: '';
    position: absolute;
    width: 100%;
    height: var(--border--size);
    bottom: 0.1em;
    left: 0;
    background-color: currentColor;

    -webkit-transform-origin: right;
    transform-origin: right;

    -webkit-transform: scaleX(0);
    transform: scaleX(0);

    -webkit-transition: 0.6s transform cubic-bezier(0.66, 0, 0.15, 1);
    transition: 0.6s transform cubic-bezier(0.66, 0, 0.15, 1);
  }
  .hover-line,
  .line-hover-inner {
    --line-spacing: 1rem;
    position: relative;
    overflow: hidden;
    display: inline-block;
    vertical-align: bottom;
  }
  .hover-line:not([data-hover='line-inner'])::before,
  .hover-line:not([data-hover='line-inner'])::after,
  .line-hover-inner::before,
  .line-hover-inner::after {
    content: '';
    position: absolute;
    display: block;
    bottom: 0.2em;
    width: 100%;
    height: var(--border--size);
    background-color: currentColor;
    -webkit-transition: 0.6s transform cubic-bezier(0.66, 0, 0.15, 1);
    transition: 0.6s transform cubic-bezier(0.66, 0, 0.15, 1);
  }
  .hover-line.line-bold:not([data-hover='line-inner'])::before,
  .hover-line.line-bold:not([data-hover='line-inner'])::after,
  .hover-line.line-bold .line-hover-inner::after,
  .hover-line.line-bold .line-hover-inner::before {
    height: 0.4rem;
    bottom: 0em;
  }
  .hover-line.line-semi:not([data-hover='line-inner'])::before,
  .hover-line.line-semi:not([data-hover='line-inner'])::after,
  .hover-line.line-semi .line-hover-inner::after,
  .hover-line.line-semi .line-hover-inner::before {
    height: 0.2rem;
    bottom: 0.1em;
  }
  .hover-line:not([data-hover='line-inner'])::before,
  .line-hover-inner::before {
    left: 0;
  }
  .hover-line:not([data-hover='line-inner'])::after,
  .line-hover-inner:after {
    left: calc(-1 * var(--line-spacing));
    transform: translateX(-100%);
  }
  .img-default {
    height: auto;
    -webkit-user-select: none;
    -khtml-user-select: none;
    -moz-user-select: none;
    -o-user-select: none;
    user-select: none;
    pointer-events: none;
    display: block;
    outline: 0;
  }
  .pe-none {
    pointer-events: none;
    -webkit-user-select: none;
    user-select: none;
  }
  .pe-none.active {
    pointer-events: auto;
    -webkit-user-select: auto;
    user-select: auto;
  }
  .us-none-select {
    -webkit-user-select: none;
    -webkit-user-drag: none;
  }
  .custom-scroll {
    overflow-y: auto;
    overflow-x: clip;
  }
  .custom-scroll-hor {
    overflow-x: auto;
    overflow-y: clip;
  }
  .custom-scroll::-webkit-scrollbar {
