  }
  .cursor-main.has-control .item-control {
    transform: scale(1);
  }
  .cursor-main.has-control-next .item-control {
    transform: scale(1) rotate(180deg);
  }
  .cursor-main.has-ic-close .item-close {
    transform: scale(1);
  }
  .cursor-main.has-control .cursor-outline,
  .cursor-main.has-link .cursor-outline {
    opacity: 0;
  }
  .cursor-main.has-link {
    border-color: transparent;
  }
  .cursor-main.has-link .cursor-link {
    opacity: 1;
    transform: scale(1);
  }
  .cursor-main.hidden {
    display: block !important;
    opacity: 0;
  }
  .merchan-popup .btn-quantity-ic-item {
    pointer-events: none;
  }
  .merchan-popup.active .btn-quantity-ic-item {
    pointer-events: all;
  }
  @media (hover: hover) and (min-width: 992px) {
    .link:hover .link-top {
      transform: translate(0, -100%);
    }
    .link:hover .link-bottom {
      transform: translate(0, 0);
    }
    .link:hover .link-ic.top {
      transform: translate(100%, -100%);
    }
    .link:hover .link-ic.bot {
      transform: translate(0, 0);
    }
    [data-cta-cursor-wrap]:hover [data-cta-cursor-el] [data-cta-cursor-el-inner] {
      opacity: 1;
    }
    .hover-un:hover::before {
      transform-origin: left;
      -webkit-transform-origin: left;

      -webkit-transform: scaleX(1);
      transform: scaleX(1);
    }
    .hover-line:hover::before,
    .hover-line:hover .line-hover-inner::before {
      -webkit-transform: translateX(calc(100% + var(--line-spacing)));
      transform: translateX(calc(100% + var(--line-spacing)));
    }
    .hover-line:hover::after,
    .hover-line:hover .line-hover-inner::after {
      -webkit-transform: translateX(var(--line-spacing));
      transform: translateX(var(--line-spacing));
    }
    .btn:hover .btn-arr-ic {
      transform: translate(100%, -100%);
    }
    [data-flipping-text] {
      position: relative;
      display: inline-block;
      overflow: hidden;
    }
    button:has([data-flipping-text]):hover span,
    [data-flipping-text]:hover span {
      transform: translateY(-1.3em) rotate(0.001deg);
    }
    .input-grp:hover .input-line-inner {
      transform: scaleX(1);
    }
  }
  @media (max-width: 992px) {
    .clamp-2-tb {
      -webkit-line-clamp: 2;
    }
    .clamp-1-tb {
      -webkit-line-clamp: 1;
    }
  }
  @media only screen and (max-width: 767px) {
    .txt-clamp-mb {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .input-grp.active .input-label,
    .input-grp.filled .input-label {
      top: 2.8rem;
    }
    .clamp-2-mb {
      -webkit-line-clamp: 2;
    }
    .clamp-3-mb {
      -webkit-line-clamp: 3;
    }
  }

  :root {
    --page-padding: max((100vw - var(--container--max-width)) / 2, 0px);
  }
  .container.grid,
  .full-width {
    --padding-inline: calc(var(--container--padding) - var(--container--column-gap));
    --content-max-width: calc(var(--container--max-width) - (var(--container--padding) * 2));

    padding: 0;
    display: grid;
    grid-template-columns:
      [full-width-start] 
      minmax(var(--padding-inline), 1fr)
      [content-start]
      repeat(var(--container--column), minmax(0, calc(min(
        100% - (var(--padding-inline) * 2) - (var(--container--column-gap) * (var(--container--column) - 1)),
        var(--content-max-width) - (var(--container--column-gap) * (var(--container--column) - 1))
      ) / var(--container--column))))
      [content-end]
      minmax(var(--padding-inline), 1fr) 
      [full-width-end];
      gap: 0 var(--container--column-gap);
  }

  .container.grid > :not(.full-width),
  .full-width > :not(.full-width) {
    grid-column: content;
  }
  /*@media only screen and (min-width: 1920px) {
    .container.grid,
    .full-width {
      --padding-inline: calc(var(--container--padding) - var(--column-gap));
    }
  }*/

  .container.grid > .full-width,
  .container.grid > .full-width-wrap {
    grid-column: full-width;

    display: grid;
    grid-template-columns: minmax(0px, 1fr);
  }

  @keyframes marquee {
    0% {
      transform: translateX(0);
    }

    100% {
      transform: translateX(-100%);
    }
  }

  .anim-marquee {
    animation: marquee 30s linear infinite;
  }
  @keyframes wave {
    0% {
      width: 50%;
      height: 50%;
      opacity: 0;
    }
    20%,
    80% {
      opacity: 0.65;
    }
    60% {
      opacity: 1;
    }
    90% {
      opacity: 0.9;
    }
    100% {
      opacity: 0;
      width: 120%;
      height: 120%;
    }
  }
