  @keyframes in-icon {
    0% {
      transform: scale(1);
      color: #373737;
    }
    20% {
      transform: scale(0.8);
      color: #373737;
    }
    60% {
      transform: scale(2.4);
      color: var(--_color---content--main);
    }
    100% {
      transform: scale(2);
      color: var(--_color---content--main);
    }
  }

  @keyframes out-icon {
    0% {
      transform: scale(2);
      color: var(--_color---content--main);
    }
    20% {
      transform: scale(2.2);
      color: #373737;
    }
    100% {
      color: #373737;
      transform: scale(1);
    }
  }
  .icon circle {
    animation-delay: var(--delay, 0s);
    transform-box: fill-box;
    transform-origin: center;
    color: #373737;
    transform: scale(1);

    animation-duration: 0.5s;
    animation-timing-function: cubic-bezier(0.445, 0.05, 0.55, 0.95);
    animation-fill-mode: both;
    animation-name: out-icon;
  }

  .icon circle:nth-child(15n + 1) {
    --delay: 0.07s;
  }
  .icon circle:nth-child(15n + 2) {
    --delay: 0.28s;
  }
  .icon circle:nth-child(15n + 3) {
    --delay: 0.12s;
  }
  .icon circle:nth-child(15n + 4) {
    --delay: 0.36s;
  }
