    --delay: 0.02s;
  }
  .icon circle:nth-child(15n + 6) {
    --delay: 0.19s;
  }
  .icon circle:nth-child(15n + 7) {
    --delay: 0.42s;
  }
  .icon circle:nth-child(15n + 8) {
